import React, { useEffect, useMemo, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  ChevronRight,
  Coffee,
  Croissant,
  CupSoda,
  Heart,
  LayoutGrid,
  Minus,
  Package,
  Plus,
  Search,
  Settings2,
  ShoppingCart,
  Store,
  User,
  X
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useCart } from "./CartContext";
import { useTheme } from "./ThemeContext";
import { apiFetch } from "./api";
import { CATEGORIES, FILTERS, productBadge, productMatchesFilter, refFromId } from "./catalog";
import { h, f } from "./h";
import {
  Badge,
  Button,
  Field,
  GlassCard,
  GlassPanel,
  LogoMark,
  RefImage,
  TextInput,
  ThemeToggleButton
} from "./ui";

function BuyerHeader({ onOpenCart, title, hideSearch, searchValue, onSearchChange, onSearchSubmit }) {
  const { dark, toggle } = useTheme();
  const { count } = useCart();
  const nav = useNavigate();

  const submitSearch = () => {
    onSearchSubmit?.();
  };

  return h(
    "header",
    {
      className:
        "sticky top-0 z-40 border-b border-white/10 bg-white/30 shadow-sm backdrop-blur-xl dark:bg-night-900/40"
    },
    h("div", { className: "mx-auto flex max-w-7xl flex-col gap-3 px-4 py-3 sm:flex-row sm:items-center sm:justify-between sm:gap-4 sm:px-6" }, [
      h("div", { key: "row-brand", className: "flex items-center justify-between gap-3 sm:justify-start" }, [
        h(Link, { key: "brand-link", to: "/shop", className: "flex items-center gap-2" }, [
          h(LogoMark, { key: "lm", className: "h-9 w-9" }),
          h("div", { key: "titles", className: "leading-tight" }, [
            h("span", { key: "brand", className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "BrewMart"),
            title
              ? h(
                  "span",
                  {
                    key: "subtitle",
                    className:
                      "ml-2 rounded-full bg-sky-500/15 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-sky-700 dark:text-sky-300"
                  },
                  title
                )
              : null
          ])
        ]),
        h("div", { key: "mobile-actions", className: "flex items-center gap-2 sm:hidden" }, [
          h(ThemeToggleButton, { key: "th", dark, onToggle: toggle }),
          h(
            Button,
            {
              key: "m-vendor",
              variant: "primary",
              className: "!min-h-[44px] !rounded-full !px-3 !text-xs sm:!text-sm",
              type: "button",
              onClick: () => nav("/login", { state: { from: "vendor" } })
            },
            "Login"
          )
        ])
      ]),
      !hideSearch &&
        h("div", { key: "row-search", className: "flex flex-1 items-center gap-2" }, [
          h("div", { key: "search-wrap", className: "relative flex flex-1 items-center" }, [
            h(Search, {
              key: "ic-search",
              className: "pointer-events-none absolute left-3 h-4 w-4 text-slate-400"
            }),
            h(TextInput, {
              key: "input",
              value: searchValue ?? "",
              onChange: (e) => onSearchChange?.(e.target.value),
              onKeyDown: (e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  submitSearch();
                }
              },
              placeholder: "Search products, brands…",
              className: "!rounded-full !pl-10 !pr-24"
            }),
            h(
              Button,
              {
                key: "submit",
                variant: "primary",
                className: "!absolute right-1 top-1/2 !min-h-[36px] -translate-y-1/2 !rounded-full !px-4 !py-2 !text-sm",
                type: "button",
                onClick: submitSearch
              },
              "Search"
            )
          ])
        ]),
      h(
        "div",
        { key: "row-mobile-nav", className: "flex items-center justify-center gap-1 border-t border-white/10 pt-2 sm:hidden" },
        [
          h(
            Link,
            {
              key: "m-orders",
              to: "/orders",
              className:
                "tap-target flex flex-1 items-center justify-center gap-1 rounded-xl py-2 text-xs font-medium text-slate-700 dark:text-slate-200"
            },
            [h(Package, { key: "i", className: "h-4 w-4" }), h("span", { key: "t" }, "Orders")]
          ),
          h(
            Link,
            {
              key: "m-profile",
              to: "/profile",
              className:
                "tap-target flex flex-1 items-center justify-center gap-1 rounded-xl py-2 text-xs font-medium text-slate-700 dark:text-slate-200"
            },
            [h(User, { key: "i", className: "h-4 w-4" }), h("span", { key: "t" }, "Profile")]
          ),
          h(
            Button,
            {
              key: "m-cart",
              variant: "ghost",
              className: "flex-1 !min-h-[40px] !rounded-xl !py-2 !text-xs",
              type: "button",
              onClick: onOpenCart
            },
            [h(ShoppingCart, { key: "i", className: "h-4 w-4" }), h("span", { key: "t" }, "Cart")]
          )
        ]
      ),
      h("div", { key: "row-desktop", className: "hidden items-center gap-2 sm:flex" }, [
        h(ThemeToggleButton, { key: "th", dark, onToggle: toggle }),
        h(
          Link,
          {
            key: "d-orders",
            to: "/orders",
            className:
              "tap-target inline-flex items-center gap-1 rounded-2xl px-3 text-sm font-medium text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
          },
          [h(Package, { key: "i", className: "h-4 w-4" }), h("span", { key: "t", className: "hidden lg:inline" }, "Orders")]
        ),
        h(
          Link,
          {
            key: "d-profile",
            to: "/profile",
            className:
              "tap-target inline-flex items-center gap-1 rounded-2xl px-3 text-sm font-medium text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
          },
          [h(User, { key: "i", className: "h-4 w-4" }), h("span", { key: "t", className: "hidden lg:inline" }, "Profile")]
        ),
        h(
          Button,
          {
            key: "d-cart",
            variant: "ghost",
            className: "relative !min-h-[44px]",
            type: "button",
            onClick: onOpenCart
          },
          [
            h(ShoppingCart, { key: "i", className: "h-5 w-5" }),
            h("span", { key: "t", className: "hidden sm:inline" }, "Cart"),
            count > 0 &&
              h(
                "span",
                {
                  key: "count",
                  className:
                    "absolute -right-1 -top-1 flex h-5 min-w-[1.25rem] items-center justify-center rounded-full bg-sky-500 px-1 text-[10px] font-bold text-white"
                },
                String(count)
              )
          ]
        ),
        h(
          Button,
          {
            key: "d-vendor",
            variant: "primary",
            className: "!min-h-[44px] !rounded-full !px-4 !text-sm sm:!px-5",
            type: "button",
            onClick: () => nav("/login", { state: { from: "vendor" } })
          },
          "Login"
        )
      ])
    ])
  );
}

function CategoryRow({ active, onSelect }) {
  const icons = {
    all: Store,
    coffee: Coffee,
    beans: Package,
    gear: Settings2,
    snacks: Croissant,
    mugs: CupSoda
  };
  return h(
    "div",
    { className: "no-scrollbar -mx-4 flex gap-3 overflow-x-auto px-4 pb-2 sm:mx-0 sm:flex-wrap sm:overflow-visible sm:px-0" },
    CATEGORIES.map((c) => {
      const Icon = icons[c.id] || LayoutGrid;
      const isOn = active === c.id;
      return h(
        "button",
        {
          key: c.id,
          type: "button",
          onClick: () => onSelect(c.id),
          className: `flex min-w-[4.5rem] flex-col items-center gap-1 rounded-2xl border px-3 py-2 text-xs font-medium transition sm:min-w-0 sm:flex-row sm:gap-2 sm:px-4 sm:text-sm ${
            isOn
              ? "border-sky-500/50 bg-sky-500/15 text-slate-900 dark:border-sky-400/40 dark:text-white"
              : "border-transparent bg-white/30 text-slate-700 hover:bg-white/50 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
          }`
        },
        [
          h(
            "span",
            {
              key: "ic",
              className: `flex h-10 w-10 items-center justify-center rounded-full sm:h-9 sm:w-9 ${
                isOn ? "bg-sky-600 text-white" : "bg-slate-200/80 text-slate-700 dark:bg-night-800 dark:text-slate-200"
              }`
            },
            h(Icon, { className: "h-5 w-5" })
          ),
          h("span", { key: "lb" }, c.label)
        ]
      );
    })
  );
}

export function CartDrawer({ open, onClose }) {
  const { items, subtotal, setQty, remove, clear } = useCart();
  const { accessToken } = useAuth();
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");

  const checkout = async () => {
    setErr("");
    if (!accessToken) {
      window.location.assign("/login");
      return;
    }
    if (items.length === 0 || subtotal <= 0) return;
    setLoading(true);
    try {
      const checkoutBody = {
        items: items.map((p) => ({ productId: p.id, quantity: p.qty }))
      };
      const { order } = await apiFetch("/api/orders/checkout", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: checkoutBody
      });
      const data = await apiFetch("/api/payments/create-checkout-session", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { orderId: order.id }
      });
      if (data.url) {
        clear();
        window.location.href = data.url;
      } else {
        setErr("Checkout session missing redirect URL. Is Stripe configured?");
      }
    } catch (ex) {
      setErr(ex.message || "Checkout failed");
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;
  return h(
    "div",
    { className: "fixed inset-0 z-50 flex justify-end" },
    [
      h("button", {
        key: "overlay",
        type: "button",
        className: "absolute inset-0 bg-slate-950/60 backdrop-blur-sm",
        onClick: onClose,
        "aria-label": "Close cart overlay"
      }),
      h(
        GlassPanel,
        {
          key: "panel",
          className: "relative z-10 m-0 h-full w-full max-w-md rounded-none border-l border-white/10 sm:m-4 sm:h-[calc(100%-2rem)] sm:rounded-3xl",
          onClick: (e) => e.stopPropagation()
        },
        [
          h("div", { key: "head", className: "flex items-center justify-between border-b border-white/10 pb-4" }, [
            h("div", { key: "title-wrap", className: "flex items-center gap-2" }, [
              h(ShoppingCart, { key: "ic", className: "h-5 w-5 text-sky-400" }),
              h("h2", { key: "tx", className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Your cart")
            ]),
            h(
              "button",
              {
                key: "close",
                type: "button",
                className: "tap-target rounded-2xl p-2 hover:bg-white/10",
                onClick: onClose
              },
              h(X, { className: "h-5 w-5" })
            )
          ]),
          h("div", { key: "items", className: "mt-4 flex max-h-[55vh] flex-col gap-3 overflow-y-auto pr-1" }, [
            items.length === 0 &&
              h("p", { key: "empty", className: "text-sm text-slate-500 dark:text-slate-400" }, "Your cart is empty."),
            items.map((p) =>
              h(GlassCard, { key: p.id, className: "!p-3" }, [
                h("div", { key: "row", className: "flex gap-3" }, [
                  h(RefImage, {
                    key: "img",
                    src: p.imageUrls?.[0],
                    n: refFromId(p.id),
                    alt: p.name,
                    className: "h-16 w-16 shrink-0 rounded-xl"
                  }),
                  h("div", { key: "meta", className: "min-w-0 flex-1" }, [
                    h("p", { key: "name", className: "truncate font-semibold text-slate-900 dark:text-white" }, p.name),
                    h("p", { key: "desc", className: "text-xs text-slate-500 dark:text-slate-400" }, p.blurb || p.description || ""),
                    h("p", { key: "price", className: "mt-1 text-sm font-bold text-sky-600 dark:text-sky-300" }, `$${p.price.toFixed(2)}`),
                    h("div", { key: "qty", className: "mt-2 flex items-center gap-2" }, [
                      h(
                        "button",
                        {
                          key: "dec",
                          type: "button",
                          className: "tap-target rounded-xl border border-white/15 p-2 hover:bg-white/10",
                          onClick: () => setQty(p.id, p.qty - 1)
                        },
                        h(Minus, { className: "h-4 w-4" })
                      ),
                      h("span", { key: "count", className: "w-6 text-center text-sm font-semibold" }, String(p.qty)),
                      h(
                        "button",
                        {
                          key: "inc",
                          type: "button",
                          className: "tap-target rounded-xl border border-white/15 p-2 hover:bg-white/10",
                          onClick: () => setQty(p.id, p.qty + 1)
                        },
                        h(Plus, { className: "h-4 w-4" })
                      ),
                      h(
                        "button",
                        {
                          key: "rm",
                          type: "button",
                          className: "ml-auto text-xs font-semibold text-rose-400 hover:underline",
                          onClick: () => remove(p.id)
                        },
                        "Remove"
                      )
                    ])
                  ])
                ])
              ])
            )
          ]),
          err && h("p", { key: "err", className: "mt-3 text-sm text-rose-400" }, err),
          h("div", { key: "totals", className: "mt-6 space-y-2 border-t border-white/10 pt-4 text-sm" }, [
            h("div", { key: "subtotal", className: "flex justify-between text-slate-600 dark:text-slate-400" }, [
              h("span", { key: "l" }, "Subtotal"),
              h("span", { key: "v", className: "font-semibold text-slate-900 dark:text-white" }, `$${subtotal.toFixed(2)}`)
            ]),
            h("div", { key: "delivery", className: "flex justify-between text-slate-600 dark:text-slate-400" }, [
              h("span", { key: "l" }, "Delivery"),
              h("span", { key: "v", className: "font-semibold text-emerald-400" }, "Free")
            ]),
            h("div", { key: "total", className: "flex justify-between text-lg font-bold text-slate-900 dark:text-white" }, [
              h("span", { key: "l" }, "Total"),
              h("span", { key: "v" }, `$${subtotal.toFixed(2)}`)
            ]),
            h(
              Button,
              {
                key: "checkout",
                className: "mt-3 w-full !rounded-2xl",
                onClick: checkout,
                loading,
                disabled: items.length === 0
              },
              [h("span", { key: "tx" }, "Proceed to checkout "), h(ChevronRight, { key: "ic", className: "h-4 w-4" })]
            )
          ])
        ]
      )
    ]
  );
}

export function ShopPage() {
  const [cat, setCat] = useState("all");
  const [fil, setFil] = useState("all");
  const [cartOpen, setCartOpen] = useState(false);
  const [queryInput, setQueryInput] = useState("");
  const [searchQ, setSearchQ] = useState("");
  const [products, setProducts] = useState([]);
  const [listErr, setListErr] = useState("");
  const [listLoading, setListLoading] = useState(true);
  const { add } = useCart();

  useEffect(() => {
    const t = setTimeout(() => setSearchQ(queryInput.trim()), 350);
    return () => clearTimeout(t);
  }, [queryInput]);

  useEffect(() => {
    let cancelled = false;
    setListLoading(true);
    const params = new URLSearchParams();
    if (cat !== "all") params.set("category", cat);
    if (searchQ) params.set("q", searchQ);
    const qs = params.toString();
    apiFetch(`/api/products${qs ? `?${qs}` : ""}`)
      .then((d) => {
        if (!cancelled) setProducts(d.products || []);
      })
      .catch((ex) => {
        if (!cancelled) {
          setListErr(ex.message || "Could not load products");
          setProducts([]);
        }
      })
      .finally(() => {
        if (!cancelled) setListLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [cat, searchQ]);

  const filtered = useMemo(() => {
    return products.filter((p) => productMatchesFilter(p, fil));
  }, [products, fil]);

  return h("div", { className: "min-h-screen pb-24" }, [
    h(BuyerHeader, {
      key: "hdr",
      onOpenCart: () => setCartOpen(true),
      searchValue: queryInput,
      onSearchChange: setQueryInput,
      onSearchSubmit: () => setSearchQ(queryInput.trim())
    }),
    h("div", { key: "main", className: "relative mx-auto max-w-7xl px-4 py-6 sm:px-6" }, [
      h(RefImage, {
        key: "bg-blur",
        n: 4,
        alt: "",
        className: "pointer-events-none absolute left-1/2 top-0 -z-10 h-64 w-full max-w-3xl -translate-x-1/2 rounded-[2rem] object-cover opacity-25 blur-2xl dark:opacity-20"
      }),
      h("section", { key: "cats", className: "mb-8" }, h(CategoryRow, { active: cat, onSelect: setCat })),
      h(
        GlassCard,
        {
          key: "hero-card",
          className: "relative mb-10 overflow-hidden !border-sky-500/20 !bg-gradient-to-br !from-sky-900/90 !to-night-950 !p-0 !shadow-2xl"
        },
        h("div", { className: "grid gap-6 p-6 sm:grid-cols-2 sm:items-center sm:p-10" }, [
          h("div", { key: "hero-copy", className: "space-y-4" }, [
            h(
              "h1",
              { key: "h1", className: "font-display text-3xl font-bold leading-tight text-white sm:text-4xl" },
              "Discover premium coffee & more"
            ),
            h(
              "p",
              { key: "sub", className: "max-w-md text-sm text-white/85 sm:text-base" },
              "Handpicked products from artisan vendors around the world."
            ),
            h("div", { key: "hero-btns", className: "flex flex-wrap gap-3" }, [
              h(
                Button,
                {
                  key: "shop-now",
                  variant: "ghost",
                  className: "!border-white/40 !bg-white/90 !text-slate-900 hover:!bg-white"
                },
                "Shop now"
              ),
              h(
                Button,
                {
                  key: "browse-cat",
                  variant: "ghost",
                  className: "!border-white/50 !bg-transparent !text-white hover:!bg-white/10"
                },
                "Browse categories"
              )
            ])
          ]),
          h(
            "div",
            { key: "hero-img", className: "relative hidden sm:block" },
            h(RefImage, { n: 11, alt: "Hero", className: "h-56 w-full rounded-3xl object-cover opacity-90" })
          )
        ])
      ),
      h("div", { key: "filters-row", className: "mb-4 flex flex-wrap items-center gap-2" }, [
        h("span", { key: "flabel", className: "text-sm font-semibold text-slate-600 dark:text-slate-300" }, "Filter:"),
        FILTERS.map((fitem) =>
          h(
            "button",
            {
              key: fitem.id,
              type: "button",
              onClick: () => setFil(fitem.id),
              className: `tap-target rounded-full px-4 py-2 text-sm font-medium transition ${
                fil === fitem.id
                  ? "bg-sky-600 text-white shadow-lg shadow-sky-900/30"
                  : "glass text-slate-700 hover:bg-white/50 dark:text-slate-200 dark:hover:bg-white/10"
              }`
            },
            fitem.label
          )
        )
      ]),
      listErr && h("p", { key: "list-err", className: "mb-4 text-sm text-rose-400" }, listErr),
      h("h2", { key: "feat-h2", className: "mb-4 font-display text-xl font-bold text-slate-900 dark:text-white sm:text-2xl" }, "Featured products"),
      listLoading &&
        h("p", { key: "list-load", className: "mb-4 text-sm text-slate-500 dark:text-slate-400" }, "Loading products…"),
      h(
        "div",
        { key: "product-grid", className: "grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4" },
        filtered.map((p) => {
          const badge = productBadge(p);
          return h(GlassCard, { key: p.id, className: "flex flex-col !p-4" }, [
            h("div", { key: "img", className: "relative" }, [
              badge
                ? h(
                    "span",
                    {
                      key: "bdg",
                      className:
                        "absolute left-2 top-2 rounded-full bg-amber-500/90 px-2 py-0.5 text-[10px] font-bold uppercase text-slate-900"
                    },
                    badge
                  )
                : null,
              h(RefImage, {
                key: "pic",
                src: p.imageUrls?.[0],
                n: refFromId(p.id),
                alt: p.name,
                className: "h-40 w-full rounded-2xl object-cover sm:h-44"
              })
            ].filter(Boolean)),
            h("div", { key: "title-row", className: "mt-3 flex items-start justify-between gap-2" }, [
              h("div", { key: "titles", className: "min-w-0" }, [
                h("h3", { key: "n", className: "truncate font-semibold text-slate-900 dark:text-white" }, p.name),
                h("p", { key: "c", className: "text-xs capitalize text-slate-500 dark:text-slate-400" }, p.category)
              ]),
              h(
                "button",
                {
                  key: "wish",
                  type: "button",
                  className: "tap-target rounded-xl p-2 text-slate-400 hover:bg-white/10 hover:text-rose-400",
                  "aria-label": "Wishlist"
                },
                h(Heart, { className: "h-5 w-5" })
              )
            ]),
            h("div", { key: "price-row", className: "mt-2 flex items-center justify-between" }, [
              h("span", { key: "pr", className: "text-lg font-bold text-sky-600 dark:text-sky-300" }, `$${Number(p.price).toFixed(2)}`),
              h("span", { key: "st", className: "text-xs text-slate-500 dark:text-slate-400" }, `${p.stock ?? 0} in stock`)
            ]),
            h(
              Button,
              {
                key: "add",
                variant: "ghost",
                className: "mt-3 w-full !justify-center !rounded-2xl border-sky-500/30",
                type: "button",
                disabled: (p.stock ?? 0) <= 0,
                onClick: () => add(p, 1)
              },
              [
                h(ShoppingCart, { key: "ic", className: "h-4 w-4" }),
                h("span", { key: "tx" }, (p.stock ?? 0) <= 0 ? "Out of stock" : "Add to cart")
              ]
            )
          ]);
        })
      )
    ]),
    h(CartDrawer, { key: "cart", open: cartOpen, onClose: () => setCartOpen(false) }),
    h(
      "button",
      {
        key: "fab-cart",
        type: "button",
        className:
          "fixed bottom-4 right-4 z-30 flex items-center gap-2 rounded-full bg-gradient-to-r from-sky-500 to-blue-600 px-5 py-3 text-sm font-semibold text-white shadow-xl shadow-sky-900/40 sm:hidden",
        onClick: () => setCartOpen(true)
      },
      [h(ShoppingCart, { key: "i", className: "h-5 w-5" }), h("span", { key: "t" }, "Cart")]
    )
  ]);
}

function orderStatusTone(status) {
  if (status === "delivered" || status === "paid") return "success";
  if (status === "shipped" || status === "processing") return "warn";
  if (status === "cancelled") return "danger";
  if (status === "pending_payment") return "info";
  return "neutral";
}

function humanizeOrderStatus(s) {
  return String(s || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export function OrdersPage() {
  const [cartOpen, setCartOpen] = useState(false);
  const { accessToken } = useAuth();
  const [orders, setOrders] = useState([]);
  const [drafts, setDrafts] = useState({});
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!accessToken) {
      setOrders([]);
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    apiFetch("/api/orders", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (!cancelled) setOrders(d.orders || []);
      })
      .catch((ex) => {
        if (!cancelled) setErr(ex.message || "Could not load orders");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const sendMessage = async (orderId) => {
    if (!accessToken) return;
    const text = (drafts[orderId] || "").trim();
    if (!text) return;
    try {
      const data = await apiFetch(`/api/orders/${orderId}/messages`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { text }
      });
      setOrders((prev) => prev.map((o) => (o.id === orderId ? data.order : o)));
      setDrafts((prev) => ({ ...prev, [orderId]: "" }));
    } catch (ex) {
      setErr(ex.message || "Could not send message");
    }
  };

  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { key: "hdr", onOpenCart: () => setCartOpen(true), title: "Shop", hideSearch: true }),
    h("div", { key: "main", className: "mx-auto max-w-4xl px-4 py-8 sm:px-6" }, [
      h("div", { key: "title-row", className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
        h("h1", { key: "title", className: "flex items-center gap-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, [
          h(Package, { key: "ic", className: "h-7 w-7 text-sky-400" }),
          h("span", { key: "tx" }, "My orders")
        ]),
        h(
          Link,
          { key: "shop-link", to: "/shop" },
          h(Button, { variant: "ghost", className: "!rounded-full" }, "Shop more")
        )
      ]),
      !accessToken
        ? h("p", { key: "guest", className: "mb-4 text-sm text-amber-400" }, "Log in to see your order history.")
        : null,
      err ? h("p", { key: "err", className: "mb-4 text-sm text-rose-400" }, err) : null,
      loading ? h("p", { key: "load", className: "text-sm text-slate-500 dark:text-slate-400" }, "Loading orders…") : null,
      h("div", { key: "list", className: "space-y-4" }, [
        orders.map((o) => {
          const first = o.items?.[0];
          const when = o.createdAt ? new Date(o.createdAt).toLocaleDateString() : "";
          return h(
            GlassCard,
            { key: o.id, className: "flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between" },
            [
              h("div", { key: "row", className: "flex min-w-0 flex-1 gap-3" }, [
                h(RefImage, {
                  key: "thumb",
                  src: undefined,
                  n: first ? refFromId(first.productId) : 1,
                  alt: first?.name || "Order",
                  className: "h-14 w-14 shrink-0 rounded-xl object-cover"
                }),
                h("div", { key: "meta", className: "min-w-0" }, [
                  h("p", { key: "id", className: "font-semibold text-slate-900 dark:text-white" }, `Order #${o.id.slice(-8)}`),
                  h(
                    "p",
                    { key: "sum",
                      className: "text-sm text-slate-500 dark:text-slate-400"
                    },
                    `${first ? `${first.name}${o.items.length > 1 ? ` +${o.items.length - 1} more` : ""}` : "Items"} · ${when} · $${Number(o.total).toFixed(2)}`
                  ),
                  o.sellerContacts?.[0] &&
                    h("div", { key: "contact", className: "mt-2 flex flex-wrap gap-2 text-xs" }, [
                      o.sellerContacts[0].phone &&
                        h("a", { key: "ph", href: `tel:${o.sellerContacts[0].phone}`, className: "text-sky-600 hover:underline dark:text-sky-300" }, "Call vendor"),
                      o.sellerContacts[0].email &&
                        h("a", { key: "em", href: `mailto:${o.sellerContacts[0].email}`, className: "text-sky-600 hover:underline dark:text-sky-300" }, "Email vendor")
                    ].filter(Boolean))
                ])
              ]),
              h(Badge, { key: "st", tone: orderStatusTone(o.status) }, humanizeOrderStatus(o.status)),
              h("div", { key: "chat", className: "w-full space-y-2 sm:max-w-sm" }, [
                h("div", { key: "msgs", className: "max-h-24 space-y-1 overflow-y-auto rounded-xl border border-white/10 p-2 text-xs" }, [
                  ...(o.messages || []).slice(-3).map((m, idx) =>
                    h("p", { key: `${m.createdAt || idx}` }, `${m.senderRole === "buyer" ? "You" : "Vendor"}: ${m.text}`)
                  )
                ]),
                h("div", { key: "composer", className: "flex gap-2" }, [
                  h(TextInput, {
                    key: "in",
                    value: drafts[o.id] || "",
                    onChange: (e) => setDrafts((prev) => ({ ...prev, [o.id]: e.target.value })),
                    placeholder: "Message vendor…",
                    className: "!min-h-[36px] !text-xs"
                  }),
                  h(Button, { key: "send", variant: "ghost", className: "!min-h-[36px] !px-3 !text-xs", onClick: () => sendMessage(o.id) }, "Send")
                ])
              ])
            ]
          );
        })
      ])
    ]),
    h(CartDrawer, { key: "cart", open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

export function ProfilePage() {
  const [cartOpen, setCartOpen] = useState(false);
  const { user, accessToken, setUser } = useAuth();
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [orderCount, setOrderCount] = useState(0);
  const [spent, setSpent] = useState(0);
  const [saveErr, setSaveErr] = useState("");
  const [saveOk, setSaveOk] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!accessToken) {
      setDisplayName("");
      setEmail("");
      setPhone("");
      setOrderCount(0);
      setSpent(0);
      return;
    }
    let cancelled = false;
    apiFetch("/api/auth/me", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled || !d.user) return;
        setDisplayName(d.user.displayName || "");
        setEmail(d.user.email || "");
        setPhone(d.user.phone || "");
      })
      .catch(() => {});
    apiFetch("/api/orders", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled) return;
        const list = d.orders || [];
        setOrderCount(list.length);
        const paid = list.filter((o) => ["paid", "processing", "shipped", "delivered"].includes(o.status));
        setSpent(paid.reduce((s, o) => s + Number(o.total || 0), 0));
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const saveProfile = async () => {
    setSaveErr("");
    setSaveOk("");
    if (!accessToken) return;
    setSaving(true);
    try {
      const data = await apiFetch("/api/auth/profile", {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { displayName: displayName.trim(), phone: phone.trim() }
      });
      if (data.user) setUser(data.user);
      setSaveOk("Profile updated.");
    } catch (ex) {
      setSaveErr(ex.message || "Save failed");
    } finally {
      setSaving(false);
    }
  };

  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true), hideSearch: true }),
    h("div", { className: "mx-auto max-w-3xl px-4 py-10 sm:px-6" }, [
      h("div", { className: "mb-8 flex flex-col items-center text-center" }, [
        h(RefImage, { n: 12, alt: "Profile", className: "h-24 w-24 rounded-full object-cover ring-4 ring-sky-500/30" }),
        h(
          "h1",
          { className: "mt-4 font-display text-2xl font-bold text-slate-900 dark:text-white" },
          displayName || user?.displayName || user?.email || "Your profile"
        ),
        h("p", { className: "text-sm text-slate-500 dark:text-slate-400" }, user?.email || "Sign in to sync your account")
      ]),
      h(GlassPanel, { className: "mb-6" }, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Account details"),
        h("div", { className: "mt-4 space-y-4" }, [
          h(Field, { label: "Display name" }, h(TextInput, { value: displayName, onChange: (e) => setDisplayName(e.target.value), placeholder: "Your name" })),
          h(Field, { label: "Email" }, h(TextInput, { type: "email", value: email, disabled: true })),
          h(Field, { label: "Phone" }, h(TextInput, { value: phone, onChange: (e) => setPhone(e.target.value), placeholder: "+1 …" })),
          saveErr && h("p", { className: "text-sm text-rose-400" }, saveErr),
          saveOk && h("p", { className: "text-sm text-emerald-400" }, saveOk),
          h(
            Button,
            {
              variant: "primary",
              className: "w-full sm:w-auto",
              type: "button",
              onClick: saveProfile,
              loading: saving,
              disabled: !accessToken
            },
            "Save changes"
          ),
          !accessToken &&
            h("p", { className: "text-sm text-amber-400" }, "You are browsing as a guest. Log in to persist profile changes.")
        ])
      ]),
      h(GlassCard, {}, h("div", { className: "grid grid-cols-2 gap-4 text-center sm:grid-cols-3" }, [
        h("div", {}, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, String(orderCount)),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Orders")
        ]),
        h("div", { className: "sm:col-span-1" }, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, `$${spent.toFixed(2)}`),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Spent (paid orders)")
        ])
      ]))
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

export function PaymentSuccessPage() {
  const [params] = useSearchParams();
  const { dark, toggle } = useTheme();
  const orderId = params.get("orderId") || "";
  return h("div", { className: "mx-auto max-w-lg px-4 py-8 sm:py-12" }, [
    h("div", { className: "mb-6 flex justify-end" }, h(ThemeToggleButton, { dark, onToggle: toggle })),
    h(GlassPanel, { className: "text-center" }, [
      h("h1", { className: "font-display text-2xl font-bold text-emerald-400" }, "Payment successful"),
      h("p", { className: "mt-2 text-slate-600 dark:text-slate-300" }, "Thank you — your order is confirmed."),
      orderId && h("p", { className: "mt-2 font-mono text-xs text-slate-500 dark:text-slate-400" }, `Order reference: ${orderId}`),
      h(Link, { to: "/orders", className: "mt-4 mr-2 inline-block" }, h(Button, { variant: "ghost", className: "!rounded-full" }, "View orders")),
      h(Link, { to: "/shop", className: "mt-4 inline-block" }, h(Button, { className: "!rounded-full" }, "Back to shop"))
    ])
  ]);
}

